  return c.bson({})
  return c.cbor({})
})
```

### [Case 3] Pre-registered Error Handling

```ts
app.get("/user/:id", async (c) => {
  return c.authorizationRequired()
  return c.internalServerError()
  return c.paymentRequired()
})

